'use strict';

// MODULES //

import isndarrayLike from '@stdlib/assert-is-ndarray-like';
import base from '@stdlib/ndarray-base-ndarraylike2scalar';
import format from '@stdlib/error-tools-fmtprodmsg';


// MAIN //

/**
* Converts an ndarray-like object to a scalar value.
*
* @param {ndarrayLike} x - input ndarray
* @throws {TypeError} must provide an ndarray
* @returns {*} scalar value
*
* @example
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
*
* var x = scalar2ndarray( 1.0 );
* // returns <ndarray>[ 1.0 ]
*
* var out = ndarraylike2scalar( x );
* // returns 1.0
*/
function ndarraylike2scalar( x ) {
	if ( !isndarrayLike( x ) ) {
		throw new TypeError( format( 'nullDv', x ) );
	}
	return base( x );
}


// EXPORTS //

export default ndarraylike2scalar;
